commands.command:
/bin/zsh -lc 'mkdir -p docs/acceptance/insight-owner-fresh-5a18901e/raw docs/acceptance/insight-owner-fresh-5a18901e/screenshots && {
  echo "cwd=$(pwd)";
  echo "date_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)";
  echo "branch=$(git branch --show-current)";
  echo "head=$(git rev-parse HEAD)";
  echo "origin_main=$(git rev-parse origin/main)";
  echo "status:"; git status --short;
  echo "task_input:"; find task-input/v1 -maxdepth 2 -type f -print 2>&1 || true;
} | tee docs/acceptance/insight-owner-fresh-5a18901e/raw/00-provenance.log
make build 2>&1 | tee docs/acceptance/insight-owner-fresh-5a18901e/raw/01-make-build.log'

/bin/zsh -lc 'set -euo pipefail
BASE=http://127.0.0.1:17100
for i in $(seq 1 30); do
  if curl -fsS "$BASE/api/health" >/tmp/insight-health.json 2>/tmp/insight-health.err; then break; fi
  sleep 1
done
{
 echo '"'"'$ curl -i /api/health'"'; curl -i \""'$BASE/api/health";
 echo; echo '"'"'$ curl -i /api/system/version'"'; curl -i \""'$BASE/api/system/version";
 echo; echo '"'"'$ curl -i /api/auth/bootstrap'"'; curl -i \""'$BASE/api/auth/bootstrap";
} 2>&1 | tee docs/acceptance/insight-owner-fresh-5a18901e/raw/08-runtime-http-version.log
curl -fsS -c docs/acceptance/insight-owner-fresh-5a18901e/raw/cookies.txt -H '"'content-type: application/json' \\
  -d '{\"display_name\":\"Owner Fresh\",\"email\":\"owner-fresh@example.test\",\"passcode\":\"passcode-12345\",\"organization_name\":\"Insight Fresh Org\"}' \\
  \""'$BASE/api/auth/signup" | tee docs/acceptance/insight-owner-fresh-5a18901e/raw/09-signup.json
curl -fsS -b docs/acceptance/insight-owner-fresh-5a18901e/raw/cookies.txt "$BASE/api/orgs" | tee docs/acceptance/insight-owner-fresh-5a18901e/raw/10-orgs.json'

/bin/zsh -lc 'set -euo pipefail
BASE=http://127.0.0.1:17101
RAW=docs/acceptance/insight-owner-fresh-5a18901e/raw
for i in $(seq 1 30); do curl -fsS "$BASE/api/health" >/dev/null 2>&1 && break || sleep 1; done
{
 echo '"'"'$ curl -i /api/health'"'; curl -i \""'$BASE/api/health";
 echo; echo '"'"'$ curl -i /api/system/version'"'; curl -i \""'$BASE/api/system/version";
 echo; echo '"'"'$ lsof listeners'"'; lsof -nP -iTCP:17101 -iTCP:17051 -iTCP:17301 -sTCP:LISTEN;
} 2>&1 | tee \""'$RAW/25-short-runtime-version-listeners.log"
curl -fsS -c "$RAW/short-cookies.txt" -H '"'content-type: application/json' \\
  -d '{\"display_name\":\"Owner Fresh Short\",\"email\":\"owner-fresh-short@example.test\",\"passcode\":\"passcode-12345\",\"organization_name\":\"Insight Fresh Short Org\"}' \\
  \""'$BASE/api/auth/signup" | tee "$RAW/26-short-signup.json"
curl -fsS -b "$RAW/short-cookies.txt" "$BASE/api/orgs" | tee "$RAW/27-short-orgs.json"'

/bin/zsh -lc "set -euo pipefail
BASE=http://127.0.0.1:17101
SLUG=org-6e873615
COOKIE=docs/acceptance/insight-owner-fresh-5a18901e/raw/short-cookies.txt
RAW=docs/acceptance/insight-owner-fresh-5a18901e/raw
{
 echo '"'$ GET ai-runtime clis'"'; curl -fsS -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/ai-runtime/clis"; echo;
 echo '"'"'$ GET ai-runtime models'"'; curl -fsS -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/ai-runtime/models"; echo;
 echo '"'"'$ GET agents'"'; curl -fsS -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/agents"; echo;
} | tee "$RAW/35-runtime-catalog-agents-before.log"
curl -fsS -b "$COOKIE" -H '"'content-type: application/json' \\
  -d '{\"display_name\":\"Insight Runner\",\"description\":\"fakeagent-script: /tmp/insight-fakeagent-script.jsonl\",\"role\":\"member\",\"worker_id\":\"worker-6808a12a\",\"cli\":\"fakeagent\",\"model\":\"scripted\"}' \\
  \""'$BASE/api/orgs/$SLUG/members/agent" | tee "$RAW/36-create-agent-fakeagent.json"'

/bin/zsh -lc "set -euo pipefail
BASE=http://127.0.0.1:17101
SLUG=org-6e873615
COOKIE=docs/acceptance/insight-owner-fresh-5a18901e/raw/short-cookies.txt
RAW=docs/acceptance/insight-owner-fresh-5a18901e/raw
{
 echo '"'$ overview'"'; curl -i -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/insights/overview?window=24h"; echo;
 echo '"'"'$ executions'"'; curl -i -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/insights/executions?window=24h&limit=50"; echo;
 echo '"'"'$ execution detail missing'"'; curl -i -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/insights/executions/exec-missing?window=24h"; echo;
 echo '"'"'$ invalid window'"'; curl -i -b \""'$COOKIE" "$BASE/api/orgs/$SLUG/insights/overview?window=7d"; echo;
 echo '"'"'$ unauth overview'"'; curl -i \""'$BASE/api/orgs/$SLUG/insights/overview?window=24h"; echo;
} 2>&1 | tee "$RAW/49-insight-api-raw.http"'
